# LC_0283: Move Zeroes

0이 아닌 원소의 상대 순서를 유지하면서 모든 0을 뒤로 옮긴 배열을 출력한다.

## 제약

1<=N<=10000; 원소는 signed 32-bit 정수. 원래 함수는 in-place 수정이며 반환값 대신 수정된 배열을 평가한다.

## 표준입출력 계약

첫 줄 N, 다음 줄 N개 정수.
출력은 정수 하나 또는 공백으로 구분한 정수 배열이다. 참/거짓은 각각 1/0으로 출력한다. 인덱스는 0부터 시작한다.

원래 함수는 배열을 직접 수정한다. 이 프로그램에서는 수정이 끝난 배열을 출력한다.

예제 입력과 출력은 프롬프트의 별도 예제 구역에 제시한다. 문제 명세의 모든 유효 입력에 대한 동작을 보존한다.

[공식 명세](https://leetcode.com/problems/move-zeroes/)

Public examples:
[{"input": "5\n0 1 0 3 12\n", "output": "1 3 12 0 0\n"}]
Source code:
#include <bits/stdc++.h>
using namespace std;

static bool isSpaceChar(char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
}

static string trimJava(const string& s) {
    size_t begin = 0;
    size_t end = s.size();

    while (begin < end && static_cast<unsigned char>(s[begin]) <= ' ') ++begin;
    while (end > begin && static_cast<unsigned char>(s[end - 1]) <= ' ') --end;

    return s.substr(begin, end - begin);
}

static bool parseJavaInt(const string& s, int& out) {
    if (s.empty()) return false;

    size_t i = 0;
    bool negative = false;

    if (s[i] == '+' || s[i] == '-') {
        negative = (s[i] == '-');
        ++i;
        if (i == s.size()) return false;
    }

    long long value = 0;
    const long long limit = negative ? 2147483648LL : 2147483647LL;

    for (; i < s.size(); ++i) {
        char c = s[i];
        if (c < '0' || c > '9') return false;

        value = value * 10 + (c - '0');
        if (value > limit) return false;
    }

    out = static_cast<int>(negative ? -value : value);
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string firstLine;
    if (!getline(cin, firstLine)) return 0;

    firstLine = trimJava(firstLine);
    if (firstLine.empty()) return 0;

    size_t pos = 0;
    while (pos < firstLine.size() && !isSpaceChar(firstLine[pos])) ++pos;

    string firstToken = firstLine.substr(0, pos);
    int n;
    if (!parseJavaInt(firstToken, n)) return 0;

    if (n < 0) return 0;

    vector<int> a(n);
    int count = 0;

    string line;
    while (count < n && getline(cin, line)) {
        size_t i = 0;
        while (i < line.size() && count < n) {
            while (i < line.size() && isSpaceChar(line[i])) ++i;
            if (i >= line.size()) break;

            size_t start = i;
            while (i < line.size() && !isSpaceChar(line[i])) ++i;

            string token = line.substr(start, i - start);
            int value = 0;
            if (!parseJavaInt(token, value)) value = 0;

            a[count++] = value;
        }
    }

    while (count < n) {
        a[count++] = 0;
    }

    int write = 0;
    for (int read = 0; read < n; ++read) {
        if (a[read] != 0) {
            swap(a[write], a[read]);
            ++write;
        }
    }

    for (int i = 0; i < n; ++i) {
        if (i > 0) cout << ' ';
        cout << a[i];
    }
    cout << '\n';

    return 0;
}
